/**
 * Canned replies for the demo build. Written by hand to describe how NexaLM
 * actually works; nothing here was generated by a model at runtime.
 */
export interface Canned {
  prompt: string;
  reasoning?: string;
  text: string;
}

const nat: Canned = {
  prompt: 'How does NexaLM use a Kaggle GPU when Kaggle cannot accept incoming connections?',
  reasoning:
    'The question is about NAT. Kaggle and Colab sessions cannot be reached from outside, so the control plane cannot call them. ' +
    'The answer is to reverse the direction: the worker opens an outbound WebSocket and the server pushes jobs down it. ' +
    'Worth mentioning that state lives in Postgres, so a worker vanishing does not lose the turn, and that the browser side uses SSE. ' +
    'A short numbered flow plus a small table should be clearest.',
  text: `Kaggle and Colab sessions sit behind NAT, so nothing on the internet can open a connection *to* them. NexaLM turns the direction around:

1. **The worker dials out.** When the notebook starts, \`worker.py\` opens a WebSocket to the control plane (\`wss://your.domain/worker/ws\`) and authenticates with \`WORKER_TOKEN\`.
2. **It says what it has:** GPUs, free VRAM, platform, and which models are loaded.
3. **Jobs go down that same socket.** When you send a message, the API picks a worker that holds the chat's model and sends it a \`job.assign\` frame.
4. **Tokens come back up it** as \`job.delta\` frames, and the API relays them to your browser over SSE.

The control plane keeps all state in Postgres, so a worker can disappear mid-answer and nothing is lost. A pending turn is just a row waiting for the next worker to register.

| Link | Transport | Why |
|---|---|---|
| Browser → API | SSE | One-way stream, survives proxies, resumes after a reload |
| API ↔ Worker | WebSocket, opened by the worker | The only direction NAT allows |`,
};

const code: Canned = {
  prompt: 'Show me how to stream tokens from llama-server in Python.',
  text: `\`llama-server\` speaks the OpenAI chat API, so streaming is just reading server-sent events line by line:

\`\`\`python
import json
import requests

def stream_chat(prompt: str, url: str = "http://127.0.0.1:8080"):
    body = {
        "messages": [{"role": "user", "content": prompt}],
        "stream": True,
        "temperature": 0.7,
    }
    with requests.post(f"{url}/v1/chat/completions", json=body, stream=True, timeout=600) as r:
        r.raise_for_status()
        for line in r.iter_lines(decode_unicode=True):
            if not line or not line.startswith("data: "):
                continue
            data = line[len("data: "):]
            if data == "[DONE]":
                break
            delta = json.loads(data)["choices"][0]["delta"]
            if delta.get("content"):
                yield delta["content"]

for piece in stream_chat("Explain the KV cache in one paragraph."):
    print(piece, end="", flush=True)
\`\`\`

The NexaLM worker does roughly this, with two differences: it forwards each piece to the control plane as a \`job.delta\` frame instead of printing it, and it also passes on \`reasoning_content\` for models that think before they answer.`,
};

const moe: Canned = {
  prompt: 'Which runs faster on two T4s: a big mixture-of-experts model or a dense one?',
  reasoning:
    'On T4s the limit is memory bandwidth, about 320 GB/s per card, and there is no NVLink between the two. ' +
    'Speed per token depends on how many weights each token has to read. An MoE reads only its active experts. ' +
    'Use the catalogue sizes: Qwen3 30B-A3B at 18.6 GB with about 3.3B active, Gemma 3 27B dense, Llama 3.3 70B dense at IQ2.',
  text: `On a pair of T4s the number that matters is how many bytes each token has to read, not the parameter count.

| Model | Size | Active per token | On 2× T4 |
|---|---:|---:|---|
| Qwen3 30B-A3B (MoE) | 18.6 GB | ~3.3B params | about 65 tok/s, measured |
| Gemma 3 27B (dense) | 16.5 GB | all 27B | much slower: every token reads every weight |
| Llama 3.3 70B (dense, IQ2) | 24.3 GB | all 70B | single digits |

A mixture-of-experts model sends each token through a few experts, so it reads a small slice of its weights per token. A dense model reads all of them. A T4 has about 320 GB/s of memory bandwidth and no NVLink to its neighbour, so bandwidth is the ceiling.

**Rule of thumb:** on free GPUs, pick the biggest MoE model that fits in VRAM.`,
};

export const CANNED = { nat, code, moe };

const shorten = (s: string) => (s.length > 60 ? `${s.slice(0, 57)}…` : s);

export function pickReply(prompt: string, modelName: string, kind: 'chat' | 'image'): Canned {
  const p = prompt.toLowerCase();

  if (kind === 'image') {
    return {
      prompt,
      text: `*Demo build: there is no GPU behind this page, so ${modelName} can't draw "${shorten(prompt)}".*

On a real worker, \`sd-server\` renders the picture, the worker uploads it to the control plane over HTTP, and it appears right here as a thumbnail you can click to open full size.`,
    };
  }

  if (/\b(code|python|script|function|stream|llama-server|snippet)\b/.test(p)) return { ...code, prompt };
  if (/\b(moe|dense|experts?|70b|t4s?|faster|speed|tok\/s|tokens per second)\b/.test(p)) return { ...moe, prompt };
  if (/\b(nat|websocket|worker|kaggle|colab|architecture|how does|how do|gpu)\b/.test(p)) return { ...nat, prompt };

  return {
    prompt,
    text: `This is the **demo build** of NexaLM, so there's no GPU behind this page and I can't really answer "${shorten(prompt)}".

On a real deployment your message is saved to Postgres, sent to the worker that holds **${modelName}**, and streamed back token by token from a free Kaggle or Colab GPU.

Things to try here:

- Ask how the worker reaches a GPU behind NAT
- Ask for Python code that streams from llama-server
- Ask whether MoE or dense models run faster on two T4s
- Open the **Models** tab on the right and load or unload a model`,
  };
}
